import { test } from "node:test";
import assert from "node:assert/strict";
import { mkdtemp, writeFile, rm, readFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import http from "node:http";
import { zipSync, strToU8 } from "fflate";
import { parseBook } from "../src/host/parser";
// Exercise the shipped worker and storage artifact, including restart durability.
// @ts-expect-error production artifact is generated by build
const { BookshelfLibrary } = await import("../dist/library.js");
test("EPUB spine, metadata and executable markup sanitization", () => {
  const bytes = zipSync({
    "META-INF/container.xml": strToU8(
      '<container><rootfiles><rootfile full-path="OEBPS/book.opf"/></rootfiles></container>',
    ),
    "OEBPS/book.opf": strToU8(
      '<package><metadata><dc:title>真实的 EPUB 结构</dc:title><dc:creator>作者</dc:creator></metadata><manifest><item id="one" href="one.xhtml" media-type="application/xhtml+xml"/></manifest><spine><itemref idref="one"/></spine></package>',
    ),
    "OEBPS/one.xhtml": strToU8(
      '<html><body><h1>第一章</h1><p onclick="evil()">阅读习惯 <strong>十分钟</strong></p><script>alert(1)</script><img src="https://tracker.test/a"/></body></html>',
    ),
  });
  const book = parseBook(bytes, "test.epub");
  assert.equal(book.title, "真实的 EPUB 结构");
  assert.equal(book.author, "作者");
  assert.match(book.chapters[0].blocks[1].text, /阅读习惯/);
  assert.doesNotMatch(JSON.stringify(book), /onclick|<script|tracker\.test/);
});
test("long Markdown becomes bounded chapters and preserves Unicode", () => {
  const data = strToU8(
    "# 测试\n\n" +
      Array.from({ length: 450 }, (_, i) => `中文段落 ${i} 与 < 字符`).join(
        "\n\n",
      ),
  );
  const book = parseBook(data, "test.md");
  assert.equal(book.title, "测试");
  assert.ok(book.chapters.length >= 3);
  assert.ok(book.chapters.every((c) => c.blocks.length <= 180));
});
test("single-page HTML keeps the article, resolves links and decodes GBK", () => {
  const page = `<!doctype html><html lang="en"><head><title>Slow reading - Example</title>
<meta property="og:title" content="Slow reading"><meta name="author" content="Ann Lee">
<base href="https://example.com/posts/slow.html"></head><body class="has-sidebar">
<nav>Home About</nav><div class="sidebar">Popular posts</div>
<article><header><h1>Slow reading</h1></header>
<p>${"Reading slowly helps. ".repeat(12)}<a href="../notes.html">notes</a></p>
<script>track()</script><p>Second paragraph.</p>
<div class="share-bar">Share this</div></article>
<footer>Copyright</footer></body></html>`;
  const book = parseBook(strToU8(page), "slow.html");
  assert.equal(book.title, "Slow reading");
  assert.equal(book.author, "Ann Lee");
  assert.equal(book.language, "en");
  const text = book.chapters
    .flatMap((c) => c.blocks.map((b) => b.text))
    .join("\n");
  assert.match(text, /Second paragraph/);
  assert.doesNotMatch(
    text,
    /Home About|Popular posts|Share this|Copyright|track/,
  );
  assert.match(JSON.stringify(book), /https:\/\/example\.com\/notes\.html/);
  const gbk = Buffer.concat([
    Buffer.from('<meta charset="gbk"><p>'),
    Buffer.from([0xd6, 0xd0, 0xce, 0xc4]),
    Buffer.from("</p>"),
  ]);
  assert.equal(parseBook(gbk, "gbk.htm").chapters[0].blocks[0].text, "中文");
  const long =
    "<h1>Book</h1>" +
    [1, 2, 3]
      .map((i) => `<h2>Part ${i}</h2>` + "<p>line</p>".repeat(60))
      .join("");
  assert.deepEqual(
    parseBook(strToU8(long), "long.html").chapters.map((c) => c.title),
    ["Book", "Part 1", "Part 2", "Part 3"],
  );
});
test("import web pages by link and refresh them on re-import", async () => {
  const root = await mkdtemp(path.join(tmpdir(), "bookshelf-web-"));
  let words = "reading notes";
  const server = http.createServer((req, res) => {
    if (req.url === "/post") {
      res.writeHead(200, { "content-type": "text/html; charset=gbk" });
      res.end(
        Buffer.concat([
          Buffer.from("<html><head><title>Web page</title></head><body><p>"),
          Buffer.from([0xd6, 0xd0, 0xce, 0xc4]),
          Buffer.from(` ${words}</p></body></html>`),
        ]),
      );
    } else if (req.url === "/file") {
      res.writeHead(200, { "content-type": "application/pdf" });
      res.end("%PDF");
    } else {
      res.writeHead(404);
      res.end();
    }
  });
  await new Promise<void>((resolve) => server.listen(0, "127.0.0.1", resolve));
  const base = `http://127.0.0.1:${(server.address() as any).port}`;
  try {
    const library = new BookshelfLibrary(path.join(root, "store"));
    await library.ready;
    const run = async (paths: string[]) => {
      library.startImport(paths);
      while (library.job.running) await new Promise((r) => setTimeout(r, 25));
      return library.job;
    };
    let job = await run([
      `${base}/post#top`,
      `${base}/missing`,
      `${base}/file`,
    ]);
    assert.equal(job.imported, 1);
    assert.deepEqual(
      job.errors.map((e: string) => e.split("：").pop()),
      ["网页返回 404", "链接不是网页"],
    );
    const [book] = library.state.books;
    assert.equal(book.format, "HTML");
    assert.equal(book.source, `${base}/post`);
    assert.equal(book.title, "Web page");
    assert.equal((await library.search("中文 notes")).length, 1);
    job = await run([`${base}/post`]);
    assert.equal(job.skipped, 1);
    words = "updated notes";
    job = await run([`${base}/post`]);
    assert.equal(job.imported, 1);
    assert.equal(library.state.books.length, 1);
    assert.notEqual(library.state.books[0].revision, book.revision);
    assert.equal((await library.search("updated")).length, 1);
    await library.dispose();
  } finally {
    server.close();
    await rm(root, { recursive: true, force: true });
  }
});
test("import → duplicate scan → search → annotation → persisted restart", async () => {
  const root = await mkdtemp(path.join(tmpdir(), "bookshelf-test-"));
  try {
    const source = path.join(root, "book.md");
    await writeFile(
      source,
      "---\ntitle: 习惯\nauthor: 测试作者\n---\n# 第一章\n\n每天阅读十分钟，建立习惯。\n\n## 第二章\n\n留下阅读笔记。",
    );
    const library = new BookshelfLibrary(path.join(root, "store"));
    await library.ready;
    library.startImport([source]);
    while (library.job.running) await new Promise((r) => setTimeout(r, 25));
    assert.deepEqual(library.job.errors, []);
    assert.equal(library.state.books.length, 1);
    library.startImport([source]);
    while (library.job.running) await new Promise((r) => setTimeout(r, 25));
    assert.equal(library.job.skipped, 1);
    const book = library.state.books[0];
    const hits = await library.search("阅读 十分钟");
    assert.equal(hits.length, 1);
    assert.ok(hits[0].url.includes(book.revision));
    const hit = hits[0];
    await library.call({
      action: "annotate",
      bookId: book.id,
      chapter: hit.chapter,
      block: hit.block,
      quote: hit.text,
      note: "明天实践",
    });
    await library.call({
      action: "progress",
      bookId: book.id,
      chapter: hit.chapter,
      block: hit.block,
      ratio: 0.3,
    });
    await library.dispose();
    const reopened = new BookshelfLibrary(path.join(root, "store"));
    await reopened.ready;
    assert.equal(reopened.state.annotations[0].note, "明天实践");
    assert.equal(reopened.state.books[0].progress.ratio, 0.3);
    assert.match(
      await reopened.call({ action: "exportNotes", bookId: book.id }),
      /明天实践/,
    );
    await reopened.call({ action: "remove", bookId: book.id });
    assert.equal((await reopened.call({ action: "list" })).books.length, 0);
    reopened.startImport([source]);
    while (reopened.job.running) await new Promise((r) => setTimeout(r, 25));
    assert.equal(
      (await reopened.call({ action: "list" })).books[0].progress.ratio,
      0.3,
    );
    assert.equal(reopened.state.annotations.length, 1);
    const bytes = Buffer.from("文件上传路径：中文内容正常。");
    const upload = await reopened.call({
      action: "uploadStart",
      filename: "上传示例.txt",
      size: bytes.length,
    });
    await reopened.call({
      action: "uploadChunk",
      id: upload.id,
      data: bytes.toString("base64"),
    });
    await reopened.call({ action: "uploadFinish", id: upload.id });
    assert.equal((await reopened.search("中文内容")).length, 1);
    await reopened.dispose();
  } finally {
    await rm(root, { recursive: true, force: true });
  }
});
test("bookmark dedupe → collect word and passage → grade → restart → import notes", async () => {
  const root = await mkdtemp(path.join(tmpdir(), "bookshelf-review-"));
  try {
    const source = path.join(root, "slow.md");
    await writeFile(
      source,
      "# Slow\n\n## Words\n\nResist the urge to guess. These small detours quietly enlarge your vocabulary. Read on.",
    );
    const library = new BookshelfLibrary(path.join(root, "store"));
    await library.ready;
    library.startImport([source]);
    while (library.job.running) await new Promise((r) => setTimeout(r, 25));
    const book = library.state.books[0];
    const [hit] = await library.search("detours");
    const at = { bookId: book.id, chapter: hit.chapter, block: hit.block };
    const first = await library.call({
      action: "annotate",
      kind: "bookmark",
      ...at,
    });
    const again = await library.call({
      action: "annotate",
      kind: "bookmark",
      ...at,
    });
    assert.equal(again.id, first.id);
    assert.equal(library.state.annotations.length, 1);

    const word = await library.call({
      action: "collect",
      kind: "word",
      front: "detour",
      back: "/ˈdiːtʊə/\nn. 绕路",
      term: "detours",
      ...at,
    });
    assert.equal(word.created, true);
    assert.equal(
      word.card.context,
      "These small detours quietly enlarge your vocabulary.",
    );
    const duplicate = await library.call({
      action: "collect",
      kind: "word",
      front: "Detour",
      back: "",
      ...at,
    });
    assert.equal(duplicate.created, false);
    assert.equal(duplicate.card.back, "/ˈdiːtʊə/\nn. 绕路");
    const passage = await library.call({
      action: "collect",
      kind: "passage",
      quote: "Resist the urge to guess.",
      ...at,
    });
    assert.match(passage.card.context, /enlarge your vocabulary/);

    const queue = await library.call({ action: "cards", due: true });
    assert.equal(queue.due, 2);
    assert.equal(queue.cards.length, 2);
    const preview = queue.cards[0].preview;
    assert.equal(preview.length, 4);
    assert.ok(
      preview.every((t: number, i: number) => i === 0 || t >= preview[i - 1]),
    );
    const graded = await library.call({
      action: "grade",
      id: word.card.id,
      rating: 4,
    });
    assert.ok(graded.due > Date.now() + 86400000);
    assert.equal(graded.memory.reps, 1);
    await assert.rejects(
      library.call({ action: "grade", id: word.card.id, rating: 5 }),
      /评分无效/,
    );
    const stats = await library.call({ action: "reviewStats" });
    assert.equal(stats.total, 2);
    assert.equal(stats.due, 1);
    assert.equal(stats.next, graded.due);
    const sense = {
      action: "collect",
      kind: "word",
      front: "detour",
      back: "/ˈdiːtʊə/\nn. 绕路",
      sense: "n. 绕路",
      term: "detours",
      ...at,
    };
    const sensed = await library.call(sense);
    assert.equal(sensed.created, true);
    assert.notEqual(sensed.card.id, word.card.id);
    assert.equal(sensed.card.sense, "n. 绕路");
    const sensedAgain = await library.call(sense);
    assert.equal(sensedAgain.created, false);
    assert.equal(sensedAgain.card.id, sensed.card.id);

    await library.call({
      action: "annotate",
      kind: "highlight",
      ...at,
      quote: "detours",
      note: "detour /ˈdiːtʊə/\nn. 绕路\nvt. 绕道\n\ndetours\nn. 复数",
    });
    await library.call({
      action: "annotate",
      kind: "highlight",
      ...at,
      quote: "quietly enlarge your vocabulary",
      note: "积少成多",
    });
    const { imported } = await library.call({ action: "importNotes" });
    assert.equal(imported, 1);
    await library.dispose();

    const reopened = new BookshelfLibrary(path.join(root, "store"));
    await reopened.ready;
    const all = await reopened.call({ action: "cards" });
    assert.equal(all.total, 4);
    assert.equal(
      all.cards.find((c: any) => c.id === word.card.id).memory.reps,
      1,
    );
    assert.equal(
      all.cards.find((c: any) => c.front === "quietly enlarge your vocabulary")
        .back,
      "积少成多",
    );
    await reopened.call({ action: "uncollect", id: passage.card.id });
    assert.equal((await reopened.call({ action: "reviewStats" })).total, 3);
    await reopened.dispose();
  } finally {
    await rm(root, { recursive: true, force: true });
  }
});
